<?php
namespace App\Domain\Security\Services;
use App\Models\User;use Illuminate\Support\Facades\Hash;use Illuminate\Support\Str;use PragmaRX\Google2FA\Google2FA;use RuntimeException;
class MfaService{public function __construct(private Google2FA $google2fa){}public function begin(User $user):array{$secret=$this->google2fa->generateSecretKey(32);$user->update(['mfa_secret'=>$secret,'mfa_confirmed_at'=>null,'mfa_recovery_codes'=>null]);$issuer='Assam Land Records DMS';$uri=$this->google2fa->getQRCodeUrl($issuer,$user->username,$secret);return ['secret'=>$secret,'otpauth_uri'=>$uri];}public function confirm(User $user,string $code):array{if(!$user->mfa_secret||!$this->verify($user,$code))throw new RuntimeException('Invalid verification code.');$plain=[];$hashed=[];for($i=0;$i<8;$i++){$v=Str::upper(Str::random(5).'-'.Str::random(5));$plain[]=$v;$hashed[]=Hash::make($v);}$user->update(['mfa_required'=>true,'mfa_confirmed_at'=>now(),'mfa_recovery_codes'=>$hashed]);return $plain;}public function verify(User $user,string $code):bool{return (bool)$user->mfa_secret&&$this->google2fa->verifyKey($user->mfa_secret,preg_replace('/\s+/','',$code),2);}public function useRecoveryCode(User $user,string $code):bool{$codes=$user->mfa_recovery_codes??[];foreach($codes as $i=>$hashed){if(Hash::check(Str::upper(trim($code)),$hashed)){unset($codes[$i]);$user->update(['mfa_recovery_codes'=>array_values($codes)]);return true;}}return false;}}
